/** TFR aproximado: sueldo anual ÷ 13,5 por año (sin revalorización ni impuestos). */
export function tfrEstimate(annualGross: number, years: number): number {
  if (!(annualGross > 0) || !(years > 0)) return 0;
  return Math.round((annualGross / 13.5) * years);
}
